async function remove(id) {
  await fetch("/api/items/" + id, { method: "DELETE" });
  UI.toast("Removed", "success");
  await load();
}

async function save(id, values) {
  const res = await fetch("/api/items/" + id, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(values),
  });
  if (!res.ok) {
    UI.toast("Could not save", "error");
    return false;
  }
  UI.toast("Saved", "success");
  await load();
}

function fieldsOf(item) {
  return { name: item.name, quantity: item.quantity, location: item.location, status: item.status };
}

async function load() {
  UI.loading(list);
  const res = await fetch("/api/items");
  const data = await res.json();
  let shown = data.items;
  const filter = document.getElementById("filter");
  if (filter.value !== "All") shown = shown.filter((i) => i.location === filter.value);
  count.textContent = shown.length + " " + "items";
  UI.renderList(list, shown, (item) => ({
    title: "name",
    badges: ["location", "status"],
    formats: {"quantity": "num"},
    actions: [
      { label: "Edit", onClick: () => UI.form("Edit", FIELDS, item, (values) => save(item.id, values)) },
      { label: "Delete", kind: "danger", onClick: () => remove(item.id) },
    ],
  }), "Nothing here yet. Add the first one above.");
}

document.getElementById("form").addEventListener("submit", async (ev) => {
  ev.preventDefault();
  errorBox.textContent = "";
  const name = document.getElementById("name").value;
  if (!name) {
    errorBox.textContent = "Name must not be empty";
    return;
  }
  const res = await fetch("/api/items", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name: name, quantity: parseFloat(document.getElementById("quantity").value), location: document.getElementById("location").value, status: document.getElementById("status").value }),
  });
  const data = await res.json();
  if (!res.ok) {
    errorBox.textContent = typeof data.detail === "string" ? data.detail : "Please check your input";
    return;
  }
  document.getElementById("form").reset();
  UI.toast("Added", "success");
  await load();
});
document.getElementById("filter").addEventListener("change", load);

load();"}

